function failures = bidsfun_gedai_benchmark(BIDS, opts)
% BIDSFUN_GEDAI_BENCHMARK  Ground-truth injection benchmark of GEDAI cleaning quality.
%
%   failures = bidsfun_gedai_benchmark(BIDS)
%   failures = bidsfun_gedai_benchmark(BIDS, Name, Value, ...)
%
%   Measures what GEDAI does to signal it should keep and to artifacts it should remove, on
%   real recordings, by injecting both with a known ground truth:
%
%     1. Over-cleaning. Sleep graphoelements (fast and slow spindles, K-complexes, slow
%        oscillations) are generated by cortical source patches and projected through the
%        subject's BEM leadfield. Scored by the signal-to-error ratio (SER), the preserved
%        fraction of the injected field, amplitude and morphology at the peak channel, and
%        detector recovery (count, density, amplitude) with thresholds frozen on the
%        uncleaned input. See bench.scoreSignals.
%     2. Under-cleaning. EOG (eye dipoles in a spherical head), EMG (local scalp-muscle
%        noise) and ECG (far-field cardiac dipole) are injected into the same epochs.
%        Scored by the artifact-to-residue ratio (ARR), the fraction of the artifact left,
%        temporal and spectral RRMSE, correlation, and in-band PSD ratios against the clean
%        baseline. See bench.scoreArtifacts.
%
%   Design
%   ------
%   Per recording, a subset of epochs per stage is read from the GEDAI input (the same
%   desc-hpzc .set bidsfun_gedai cleans) and concatenated - chosen as the cleanest by a
%   cheap artifact score unless selectmode says otherwise. GEDAI runs on that background
%   alone (baseline) and on the background plus each injection (one condition per
%   injection type and scale), stage group by stage group exactly as bidsfun_gedai does.
%   Every injection is compared with the baseline run on the identical background
%   (paired design): GEDAI(B + S) - GEDAI(B) estimates what survived of S, so the real
%   artifacts and real graphoelements already in the background cancel instead of being
%   miscounted. Stage groups an injection did not touch are copied from the baseline run
%   rather than cleaned again.
%
%   Required
%   --------
%   BIDS              bids.layout object.
%
%   Input paths
%   -----------
%   inputpath         Root of the GEDAI input derivatives, organised as
%                     <sub>/<ses>/<fileID>_desc-<inputdesc>_eeg<inputfileext>.
%                     Default: <BIDS root>/derivatives/<derivfolder>
%   inputdesc         desc of the input (the file bidsfun_gedai reads). Default: 'hpzc'
%   inputfileext      Must be a two-file EEGLAB .set (.set + .fdt): epochs are read from the
%                     .fdt without loading the night. Default: '.set'
%   scoringpath       Directory with sleep-scoring files (.xml, .json or .csv).
%                     Default: <BIDS root>/derivatives/scoring/scores/Manual_Checked
%   sfppath           Root passed to gedai.matchSfpFile; the SFP supplies electrode
%                     positions and the nasion for the eye and heart models. Default: <BIDS root>
%   leadfielddir      Brainstorm leadfields, <leadfielddir>/<sub>/<ses>/headmodel_surf_openmeeg.mat,
%                     or the path of one head model file.
%                     Default: <BIDS root>/../Data_Analysis/Brainstorm_db/Leadfield_PM/data
%   templatebank      .mat file with a struct 'bank' holding external event waveforms per
%                     signal class (see bench.simGraphoelements), e.g. from a neural mass
%                     model. '' = parametric waveforms only. Default: ''
%
%   Output paths
%   ------------
%   savepath          Root for outputs. Default: <BIDS root>/derivatives/<derivfolder>
%   figpath           Root for figures. Default: <savepath>/figures
%   desc              desc label of all outputs. Default: 'hpzcgedbench'
%   refresh           Re-run when the metrics file already exists. Default: false
%   plots             Write summary figures. Default: true
%
%   Written to <savepath>/<sub>/<ses>/:
%     <fileID>_desc-<desc>_metrics.tsv       long table: run, runname, condition, scale,
%                                            class, stage, metric, value
%     <fileID>_desc-<desc>_metrics.json      parameters, selected epochs, seeds, timing and
%                                            metric definitions
%     <fileID>_desc-<desc>_events.tsv        every injected event (the ground truth):
%                                            condition, id, trial_type, onset, ... (onsets in
%                                            benchmark time; epoch_orig maps to the night)
%     <fileID>_desc-<desc>_events.json       column descriptions
%     <fileID>_desc-<desc>_eventscores.tsv   per-event SER, gain, amplitude ratio,
%                                            morphology and detection outcome, per run/scale
%     <fileID>_desc-<desc>_benchmark.mat     metrics, events, per-event scores, spectra,
%                                            topographies, event-locked means, selection
%     <fileID>_desc-<desc>_benchmark.json    sidecar of the .mat
%   Figures: <figpath>/desc-<desc>/<fileID>/<fileID>_desc-<desc>_run-<i>_{summary,events,spectra,topo}.png
%   The injected data themselves are not saved (~1 GB each); they are reproducible from
%   the seeds in the sidecar.
%
%   Parallel machines
%   -----------------
%   Each recording is claimed with claimFile before any work starts and released on
%   success, on error and on Ctrl-C, keyed by desc - as in bidsfun_gedai.
%   uselocks          Claim each recording before processing it. Default: true
%   lockpath          Directory holding the claim files. Default: <savepath>/.locks
%   lockstalemin      Minutes after which a claim without heartbeat is taken over. Default: 360
%   lockheartbeatmin  Minutes between heartbeat writes. Default: 5
%
%   EEG
%   ---
%   tasklabel         BIDS task label(s) to query. Default: {'Sleep','sleep'}
%   acqlabel          BIDS acq label to query. Default: ''
%   noteegchannels    Channel indices that are not EEG (dropped, and not leadfield montage
%                     rows). Default: 257:300
%   net               'EGI256' or 'EGI128', for the default anchor channels. Default: 'EGI256'
%
%   Subject filter
%   --------------
%   subjectfilter     Cell array of subject ID strings; {} = all subjects.
%   sessionfilter     Cell array of session ID strings; {} = all sessions.
%
%   GEDAI
%   -----
%   runmode           'StageSpecific', 'StateWise' or 'WholeNight'. Default: 'StageSpecific'
%   epochlength       Sleep-epoch length in s. Default: 30
%   runs              Cell array of GEDAI run configurations; every run is benchmarked on the
%                     same injections, so configurations can be compared directly. ICA is
%                     never run here. Default: gedai.defaultRuns()
%   pooltype          'Processes' or 'Threads'. Default: 'Processes'
%
%   Epoch selection (see bench.selectEpochs)
%   ---------------
%   stages            Stage digits to include (N3 -3, N2 -2, REM 0, Wake 1). Default: [-2 -3 0 1]
%   nepochs           Epochs per stage. Peak RAM grows linearly: roughly 8 x 1.2 GB per 40
%                     epochs x 4 stages at 256 channels, plus GEDAI's own working memory.
%                     Default: 40
%   selectmode        'clean', 'random' or 'first'. Default: 'clean'
%   candidatepool     Candidates read per selected epoch ('clean'). Default: 4
%   excludetransitions  Skip epochs next to a stage change. Default: true
%   demeanepochs      Remove each channel's mean per epoch. Default: true
%
%   Background
%   ----------
%   background        'real'      - the selected epochs (default)
%                     'synthetic' - leadfield-projected 1/f sources scaled to the real
%                                   epochs' per-stage RMS; GEDAI should keep all of it
%                     'flat'      - white sensor noise only
%                     See bench.simBackground. Default: 'real'
%
%   Injection
%   ---------
%   conditions        Any of 'null', 'signals', 'eog', 'emg', 'ecg'. 'null' re-runs GEDAI
%                     on the unchanged background: the spread between two runs on identical
%                     input is the floor below which no paired metric is meaningful
%                     (null_RRMSE, null_SNR_dB, null_maxabs_uV). Default: all five
%   signals           Graphoelement classes. Default: bench.defaultSignals(net)
%   artifacts         Artifact configuration. Default: bench.defaultArtifacts()
%   signalscales      Amplitude multipliers for the graphoelements; each is a condition on the
%                     same realisation (dose-response). Default: 1
%   artifactscales    Amplitude multipliers for the artifacts. Default: 1
%   seed              Base random seed; per-recording and per-condition seeds derive from it
%                     and are written to the sidecar. Default: 1
%
%   Scoring
%   -------
%   eventpad          s added around each event window. Default: 0.25
%   welchwindow       s, Welch window for the PSD metrics. Default: 4
%
%   Output
%   ------
%   failures          cell array of structs (fileID, message, report, timestamp), also
%                     written to <savepath>/failed_files_gedai_benchmark.json
%
%   See also bench.simGraphoelements, bench.simArtifacts, bench.scoreSignals,
%   bench.scoreArtifacts, Benchmark/DESIGN.md, bidsfun_gedai.

arguments
    BIDS

    %--- Derivative folder ---
    opts.derivfolder      char = 'prep-ged'

    %--- Input paths ---
    opts.inputpath        char = ''
    opts.inputdesc        char = 'hpzc'
    opts.inputfileext     char = '.set'
    opts.scoringpath      char = fullfile(BIDS.pth, 'derivatives', 'scoring', 'scores', 'Manual_Checked')
    opts.sfppath          char = BIDS.pth
    opts.leadfielddir     char = fullfile(BIDS.pth, '..', 'Data_Analysis', 'Brainstorm_db', 'Leadfield_PM', 'data')
    opts.templatebank     char = ''

    %--- Output paths ---
    opts.savepath         char = ''
    opts.figpath          char = ''
    opts.desc             char = 'hpzcgedbench'
    opts.refresh (1,1) logical = false
    opts.plots   (1,1) logical = true

    %--- Parallel machines ---
    opts.uselocks (1,1) logical = true
    opts.lockpath         char  = ''
    opts.lockstalemin     (1,1) double {mustBePositive} = 360
    opts.lockheartbeatmin (1,1) double {mustBePositive} = 5

    %--- EEG ---
    opts.tasklabel                   = {'Sleep', 'sleep'}
    opts.acqlabel          char      = ''
    opts.noteegchannels    (1,:) double = 257:300
    opts.net {mustBeMember(opts.net, {'EGI256', 'EGI128'})} = 'EGI256'

    %--- Subject filter ---
    opts.subjectfilter     cell = {}
    opts.sessionfilter     cell = {}

    %--- GEDAI ---
    opts.runmode {mustBeMember(opts.runmode, {'WholeNight', 'StageSpecific', 'StateWise'})} = 'StageSpecific'
    opts.epochlength (1,1) double {mustBePositive} = 30
    opts.runs = []
    opts.pooltype {mustBeMember(opts.pooltype, {'Processes', 'Threads'})} = 'Processes'

    %--- Epoch selection ---
    opts.stages (1,:) double = [-2 -3 0 1]
    opts.nepochs (1,1) double {mustBeInteger, mustBePositive} = 40
    opts.selectmode {mustBeMember(opts.selectmode, {'clean', 'random', 'first'})} = 'clean'
    opts.candidatepool (1,1) double {mustBePositive} = 4
    opts.excludetransitions (1,1) logical = true
    opts.demeanepochs (1,1) logical = true

    %--- Background ---
    opts.background {mustBeMember(opts.background, {'real', 'synthetic', 'flat'})} = 'real'

    %--- Injection ---
    opts.conditions cell = {'null', 'signals', 'eog', 'emg', 'ecg'}
    opts.signals struct = struct([])
    opts.artifacts struct = struct([])
    opts.signalscales (1,:) double {mustBePositive} = 1
    opts.artifactscales (1,:) double {mustBePositive} = 1
    opts.seed (1,1) double {mustBeInteger, mustBeNonnegative} = 1

    %--- Scoring ---
    opts.eventpad (1,1) double {mustBeNonnegative} = 0.25
    opts.welchwindow (1,1) double {mustBePositive} = 4
end

fprintf('\n=== Running bidsfun_gedai_benchmark ===\n');

if isempty(opts.inputpath), opts.inputpath = fullfile(BIDS.pth, 'derivatives', opts.derivfolder); end
if isempty(opts.savepath),  opts.savepath  = fullfile(BIDS.pth, 'derivatives', opts.derivfolder); end
if isempty(opts.figpath),   opts.figpath   = fullfile(opts.savepath, 'figures'); end
if isempty(opts.lockpath),  opts.lockpath  = fullfile(opts.savepath, '.locks'); end
if isempty(opts.runs),      opts.runs      = gedai.defaultRuns(); end
if isempty(opts.signals),   opts.signals   = bench.defaultSignals(opts.net); end
if isempty(opts.artifacts), opts.artifacts = bench.defaultArtifacts(); end
unknown = setdiff(opts.conditions, {'null', 'signals', 'eog', 'emg', 'ecg'});
if ~isempty(unknown)
    error('bidsfun_gedai_benchmark:condition', 'Unknown condition(s): %s', strjoin(unknown, ', '));
end
bank = struct();
if ~isempty(opts.templatebank)
    loaded = load(opts.templatebank, 'bank');
    bank = loaded.bank;
end

%%% Query EEG files from BIDS
filesEEG = bids.query(BIDS, 'data', 'extension', '.vhdr', 'task', opts.tasklabel, 'acq', opts.acqlabel);
if isempty(filesEEG)
    error('bidsfun_gedai_benchmark:noFiles', 'No matching EEG files found in BIDS layout.');
end
scoringfiles = {};
if ~isempty(opts.scoringpath), scoringfiles = gedai.collectScoringFiles(opts.scoringpath); end

failures = {};
for ifile = 1:numel(filesEEG)
    eegFile = filesEEG{ifile};
    p       = bids.internal.parse_filename(eegFile);
    fileID  = strjoin(cellfun(@(k) [k '-' p.entities.(k)], fieldnames(p.entities), 'uni', 0), '_');
    subDir  = fullfile(['sub-' p.entities.sub], ['ses-' p.entities.ses]);

    if ~isempty(opts.subjectfilter) && ~contains(fileID, opts.subjectfilter), continue; end
    if ~isempty(opts.sessionfilter) && ~contains(fileID, opts.sessionfilter), continue; end
    fprintf('\n=== %s ===\n', fileID)

    outDir      = fullfile(opts.savepath, subDir);
    baseName    = [fileID '_desc-' opts.desc];
    metricsFile = fullfile(outDir, [baseName '_metrics.tsv']);
    if ~opts.refresh && isfile(metricsFile)
        fprintf('[skip] benchmark exists: %s\n', metricsFile)
        continue
    end

    %%% Claim the recording (see bidsfun_gedai for the reasoning behind each step)
    lockGuard = [];  %#ok<NASGU> release any claim still held from the previous iteration
    if opts.uselocks
        [lockGuard, acquired, holder] = claimFile( ...
            fullfile(opts.lockpath, [fileID '_desc-' opts.desc '.lock']), ...
            'stalemin', opts.lockstalemin, 'heartbeatmin', opts.lockheartbeatmin); %#ok<ASGLU>
        if ~acquired
            fprintf('[skip] %s: claimed by %s (pid %d) since %s\n', fileID, holder.host, holder.pid, holder.started)
            continue
        end
        if ~opts.refresh && isfile(metricsFile)
            fprintf('[skip] benchmark exists: %s\n', metricsFile)
            continue
        end
    end

    try
        KeepTime = struct();
        D = tic;

        %%% ---- Inputs ----
        inFile = fullfile(opts.inputpath, subDir, [fileID '_desc-' opts.inputdesc '_eeg' opts.inputfileext]);
        if ~isfile(inFile)
            fprintf('[skip] %s: input not found (%s)\n', fileID, inFile)
            continue
        end
        fprintf('Input  → %s\nOutput → %s\n', inFile, outDir)

        if isempty(opts.scoringpath)
            scoringfiles = gedai.collectScoringFiles(fullfile(BIDS.pth, subDir));
        end
        scoringFile = gedai.matchScoringFile(p.entities, scoringfiles);
        if isempty(scoringFile)
            error('bidsfun_gedai_benchmark:noScoring', 'No scoring file matched for %s.', fileID);
        end
        fprintf('Scoring → %s\n', scoringFile)
        scoringDigits = scoreloader(scoringFile);

        sfpFile = gedai.matchSfpFile(opts.sfppath, p.entities.sub, p.entities.ses);
        if isempty(sfpFile)
            error('bidsfun_gedai_benchmark:noSfp', 'No SFP montage found for %s.', fileID);
        end
        lfFile = opts.leadfielddir;
        if isfolder(lfFile)
            lfFile = fullfile(lfFile, ['sub-' p.entities.sub], ['ses-' p.entities.ses], 'headmodel_surf_openmeeg.mat');
        end
        if ~isfile(lfFile)
            error('bidsfun_gedai_benchmark:noLeadfield', 'No leadfield at %s.', lfFile);
        end

        %%% Header only; epochs are read from the .fdt below
        [inDir, inName, inExt] = fileparts(inFile);
        EEG = pop_loadset('filename', [inName inExt], 'filepath', inDir, 'loadmode', 'info');
        if ~isfield(EEG, 'datfile') || isempty(EEG.datfile)
            error('bidsfun_gedai_benchmark:oneFileSet', ...
                '%s stores its data inside the .set; the benchmark needs a two-file .set/.fdt.', inFile);
        end
        fdtFile = fullfile(inDir, EEG.datfile);
        epochSamples = round(opts.epochlength * EEG.srate);

        %%% ---- Epoch selection ----
        seeds = struct('base', mod(opts.seed * 1000003 + sum(double(fileID) .* (1:numel(fileID))), 2^31 - 1));
        seeds.selection = deriveSeed(seeds.base, 'selection');
        rng(seeds.selection, 'twister');
        sel = bench.selectEpochs(fdtFile, EEG.nbchan, EEG.pnts, EEG.srate, opts.epochlength, scoringDigits, ...
            'stages', opts.stages, 'nepochs', opts.nepochs, 'selectmode', opts.selectmode, ...
            'candidatepool', opts.candidatepool, 'excludetransitions', opts.excludetransitions);
        if isempty(sel.epochs)
            error('bidsfun_gedai_benchmark:noEpochs', 'None of the requested stages is scored in %s.', fileID);
        end
        stageEpoch = sel.stage;
        nEpochs    = numel(stageEpoch);
        fprintf('Selected %d epochs: %s\n', nEpochs, strjoin(arrayfun(@(st, n) sprintf('%s %d', ...
            bench.stageLabel(st), n), opts.stages, arrayfun(@(st) nnz(stageEpoch == st), opts.stages), 'uni', 0), ', '))

        data = bench.readEpochs(fdtFile, EEG.nbchan, sel.epochs, epochSamples, 'demean', opts.demeanepochs);
        notEeg = ismember({EEG.chanlocs.labels}, arrayfun(@(x) ['E' num2str(x)], opts.noteegchannels, 'uni', 0));
        data(notEeg, :) = [];
        EEG.chanlocs(notEeg) = [];
        EEG.nbchan   = size(data, 1);
        EEG.data     = [];
        EEG.datfile  = '';
        EEG.filename = '';
        EEG.pnts     = size(data, 2);
        EEG.trials   = 1;
        EEG.xmin     = 0;
        EEG.xmax     = (EEG.pnts - 1) / EEG.srate;
        EEG.times    = [];
        EEG.event    = [];
        EEG.urevent  = [];
        EEG.epoch    = [];
        EEG = gedai.assignChanlocs(EEG, BIDS, opts.sfppath, eegFile, p, fileID);
        KeepTime.selection = toc(D);

        %%% ---- Forward models and GEDAI reference ----
        removedChannels = true(numel(EEG.urchanlocs), 1);
        removedChannels([EEG.chanlocs.urchan]) = false;
        if nnz(~removedChannels) ~= EEG.nbchan
            error('bidsfun_gedai_benchmark:badChannelMismatch', ...
                'urchan indices on EEG.chanlocs do not match EEG.urchanlocs.');
        end
        fprintf('%d channel(s) were removed as bad previously\n', nnz(removedChannels))
        lfCOV = gedai.loadrefcov(lfFile, p, numel(removedChannels), removedChannels, opts.noteegchannels);
        fwd = bench.buildForward(lfFile, sfpFile, EEG.chanlocs, {EEG.urchanlocs.labels}, ...
            'noteegchannels', opts.noteegchannels, 'eyeoffset', opts.artifacts.eog.eyeoffset, ...
            'heartposition', opts.artifacts.ecg.heartposition);

        %%% Samples next to a join between non-adjacent epochs: filters ring there, so
        %%% detection and scoring skip half a second on either side.
        validMask = true(1, EEG.pnts);
        joins = find(diff(sel.epochs) ~= 1) * epochSamples;
        for j = joins
            validMask(max(1, j - round(0.5 * EEG.srate) + 1):min(EEG.pnts, j + round(0.5 * EEG.srate))) = false;
        end

        %%% ---- Background ----
        seeds.background = deriveSeed(seeds.base, 'background');
        rng(seeds.background, 'twister');
        switch opts.background
            case 'real'
                B = bench.avgRef(data);
            case {'synthetic', 'flat'}
                present = opts.stages(ismember(opts.stages, stageEpoch));
                targetRms = arrayfun(@(st) stageRms(data, stageEpoch, st, epochSamples), present);
                B = bench.avgRef(bench.simBackground(fwd, stageEpoch, EEG.srate, opts.epochlength, ...
                    opts.background, 'stages', present, 'targetrms', targetRms));
            otherwise
                error('bidsfun_gedai_benchmark:background', 'Unknown background %s.', opts.background);
        end
        clear data

        stagesPresent = opts.stages(ismember(opts.stages, stageEpoch));
        [PB, f] = bench.psdEpochs({B}, 1, stageEpoch, stagesPresent, EEG.srate, opts.epochlength, opts.welchwindow);
        psdB = struct('P', PB, 'f', f, 'stages', stagesPresent);

        %%% ---- Baseline GEDAI per run ----
        nRuns = numel(opts.runs);
        [groups, Bhat, psdBhat, runNames] = deal(cell(1, nRuns));
        metricTables = {};
        for iRun = 1:nRuns
            r = opts.runs{iRun};
            groups{iRun} = stageGroups(opts.runmode, r);
            runNames{iRun} = [opts.runmode '_' gedai.buildSaveName(r, EEG.srate, groups{iRun}.mode, groups{iRun}.modeBB)];
            fprintf('\nBaseline, run %d/%d: %s\n', iRun, nRuns, runNames{iRun})
            T0 = tic;
            Bhat{iRun} = bench.runGedai(EEG, B, stageEpoch, groups{iRun}, r, lfCOV, true(1, nEpochs), single([]), ...
                'epochlength', opts.epochlength, 'pooltype', opts.pooltype);
            KeepTime.(sprintf('gedai_baseline_run%d', iRun)) = toc(T0);
            [PBhat, ~] = bench.psdEpochs(Bhat(iRun), 1, stageEpoch, stagesPresent, EEG.srate, ...
                opts.epochlength, opts.welchwindow);
            psdBhat{iRun} = struct('P', PBhat, 'f', f, 'stages', stagesPresent);
            metricTables{end+1} = labelRows(backgroundSer(B, Bhat{iRun}, stageEpoch, stagesPresent, ...
                epochSamples, validMask), iRun, runNames{iRun}, 'baseline', 1); %#ok<AGROW>
        end

        %%% ---- Conditions ----
        details = repmat({struct()}, 1, nRuns);
        eventTables = {};
        scoreTables = {};
        for iCond = 1:numel(opts.conditions)
            condition = opts.conditions{iCond};
            seeds.(condition) = deriveSeed(seeds.base, condition);
            rng(seeds.(condition), 'twister');
            T0 = tic;
            if strcmp(condition, 'null')
                %%% GEDAI again on the unchanged background: how far apart two runs on
                %%% identical input land. This is the floor under every paired metric.
                fprintf('\nCondition null: GEDAI re-run on the unchanged background\n')
                for iRun = 1:nRuns
                    Xhat = bench.runGedai(EEG, B, stageEpoch, groups{iRun}, opts.runs{iRun}, lfCOV, true(1, nEpochs), ...
                        Bhat{iRun}, 'epochlength', opts.epochlength, 'pooltype', opts.pooltype);
                    metricTables{end+1} = labelRows(nullMetrics(Xhat, Bhat{iRun}, stageEpoch, stagesPresent, ...
                        epochSamples, validMask), iRun, runNames{iRun}, 'null', 1); %#ok<AGROW>
                    clear Xhat
                end
                KeepTime.condition_null = toc(T0);
                continue
            end
            switch condition
                case 'signals'
                    [truth, events] = bench.simGraphoelements(fwd, stageEpoch, EEG.srate, opts.epochlength, ...
                        opts.signals, 'epochorig', sel.epochs, 'templatebank', bank);
                    scales = opts.signalscales;
                    touched = false(1, nEpochs);
                    touched(unique(events.epoch)) = true;
                case {'eog', 'emg', 'ecg'}
                    [truth, events] = bench.simArtifacts(fwd, stageEpoch, EEG.srate, opts.epochlength, ...
                        condition, opts.artifacts.(condition), 'epochorig', sel.epochs);
                    scales = opts.artifactscales;
                    touched = false(1, nEpochs);
                    touched(unique(events.epoch)) = true;
                otherwise
                    error('bidsfun_gedai_benchmark:condition', 'Unknown condition %s.', condition);
            end
            truth = bench.avgRef(truth);
            fprintf('\nCondition %s: %d injected event(s) in %d epoch(s)\n', condition, height(events), nnz(touched))
            eventTables{end+1} = [table(repmat({condition}, height(events), 1), 'VariableNames', {'condition'}), events]; %#ok<AGROW>

            for scale = scales
                for iRun = 1:nRuns
                    X = B + scale * truth;
                    Xhat = bench.runGedai(EEG, X, stageEpoch, groups{iRun}, opts.runs{iRun}, lfCOV, touched, ...
                        Bhat{iRun}, 'epochlength', opts.epochlength, 'pooltype', opts.pooltype);
                    clear X
                    if strcmp(condition, 'signals')
                        [m, detail] = bench.scoreSignals(scale * truth, Xhat, Bhat{iRun}, B, events, opts.signals, ...
                            stageEpoch, EEG.srate, opts.epochlength, 'eventpad', opts.eventpad, 'validmask', validMask);
                        if ~isempty(detail.events)
                            scoreTables{end+1} = [table(repmat(iRun, height(detail.events), 1), ...
                                repmat(scale, height(detail.events), 1), 'VariableNames', {'run', 'scale'}), ...
                                detail.events]; %#ok<AGROW>
                        end
                    else
                        [m, detail] = bench.scoreArtifacts(scale * truth, Xhat, Bhat{iRun}, B, events, condition, ...
                            opts.artifacts.(condition), stageEpoch, EEG.srate, opts.epochlength, psdB, psdBhat{iRun}, ...
                            'eventpad', opts.eventpad, 'validmask', validMask, 'welchwindow', opts.welchwindow);
                    end
                    clear Xhat
                    metricTables{end+1} = labelRows(m, iRun, runNames{iRun}, condition, scale); %#ok<AGROW>
                    if scale == scales(1)
                        details{iRun}.(condition) = detail;
                    end
                end
            end
            clear truth
            KeepTime.(['condition_' condition]) = toc(T0);
        end
        clear B Bhat

        %%% ---- Outputs ----
        if ~isfolder(outDir), mkdir(outDir); end
        metrics = vertcat(metricTables{:});
        %%% vertcat({}) collapses to [] (double), not an empty table - writetable chokes on
        %%% that. Happens whenever opts.conditions injects nothing (e.g. {'null'} alone).
        allEvents = table();
        if ~isempty(eventTables), allEvents = vertcat(eventTables{:}); end
        eventScores = table();
        if ~isempty(scoreTables), eventScores = vertcat(scoreTables{:}); end

        writetable(allEvents, fullfile(outDir, [baseName '_events.tsv']), 'FileType', 'text', 'Delimiter', '\t');
        writetable(eventScores, fullfile(outDir, [baseName '_eventscores.tsv']), 'FileType', 'text', 'Delimiter', '\t');
        selection = struct('epochs', sel.epochs, 'stage', stageEpoch, 'score', sel.score, ...
            'available', sel.available, 'stages', opts.stages);
        save(fullfile(outDir, [baseName '_benchmark.mat']), 'metrics', 'allEvents', 'eventScores', 'details', ...
            'selection', 'runNames', 'seeds', '-v7.3');
        KeepTime.total = toc(D);

        parameters = rmfield(opts, {'runs', 'signals', 'artifacts'});
        sidecar = struct('Description', 'GEDAI ground-truth injection benchmark (bidsfun_gedai_benchmark)', ...
            'Sources', struct('input', inFile, 'scoring', scoringFile, 'sfp', sfpFile, 'leadfield', lfFile), ...
            'Parameters', parameters, 'Signals', opts.signals, 'Artifacts', opts.artifacts, ...
            'GEDAIRuns', {cellfun(@(r, name) runForJson(r, name), opts.runs, runNames, 'uni', 0)}, ...
            'Seeds', seeds, 'SelectedEpochs', selection, 'MetricDefinitions', metricDefinitions());
        sidecarjson(KeepTime, fullfile(outDir, [baseName '_benchmark.json']), sidecar);
        sidecarjson(KeepTime, fullfile(outDir, [baseName '_metrics.json']), sidecar);
        writeEventsJson(fullfile(outDir, [baseName '_events.json']));

        %%% Metrics file last: its existence marks the recording as done
        writetable(metrics, metricsFile, 'FileType', 'text', 'Delimiter', '\t');
        fprintf('[TSV] %s\n', metricsFile)

        if opts.plots
            figDir = fullfile(opts.figpath, ['desc-' opts.desc], fileID);
            firstScale = strcmp(metrics.condition, 'signals') & metrics.scale == opts.signalscales(1) | ...
                ismember(metrics.condition, {'eog', 'emg', 'ecg'}) & metrics.scale == opts.artifactscales(1);
            for iRun = 1:nRuns
                runRows = metrics(metrics.run == iRun & firstScale, :);
                try
                    bench.plotSummary(runRows, details{iRun}, EEG.chanlocs, figDir, sprintf('%s_run-%d', baseName, iRun));
                catch plotError
                    %%% A failed figure must not throw away an hour of GEDAI runs
                    warning('bidsfun_gedai_benchmark:plot', 'Plotting failed for %s: %s', fileID, plotError.message);
                    close all
                end
            end
        end

    catch ME
        fprintf('[ERROR] %s: %s\n', fileID, ME.message);
        failures{end+1} = struct('fileID', fileID, 'message', ME.message, 'report', ME.getReport(), ...
            'timestamp', datetime('now', 'Format', 'yyyy-MM-dd HH:mm:ss')); %#ok<AGROW>
    end

    clear lockGuard
end

if ~isempty(failures)
    fprintf('\n=== %d file(s) failed ===\n', numel(failures));
    for k = 1:numel(failures)
        fprintf('  %s: %s\n', failures{k}.fileID, failures{k}.message);
    end
    if ~isfolder(opts.savepath), mkdir(opts.savepath); end
    fid = fopen(fullfile(opts.savepath, 'failed_files_gedai_benchmark.json'), 'w');
    fprintf(fid, '%s', jsonencode([failures{:}], 'PrettyPrint', true));
    fclose(fid);
end
end % bidsfun_gedai_benchmark

% -------------------------------------------------------------------------
function seed = deriveSeed(base, name)
seed = mod(base + 7919 * sum(double(name) .* (1:numel(name))), 2^31 - 1);
end

% -------------------------------------------------------------------------
function value = stageRms(data, stageEpoch, stage, epochSamples)
% Median channel RMS of the average-referenced epochs of one stage
epochs = find(stageEpoch == stage);
total = zeros(size(data, 1), 1);
for iEpoch = epochs
    x = double(bench.avgRef(data(:, (iEpoch - 1) * epochSamples + 1:iEpoch * epochSamples)));
    total = total + mean(x.^2, 2);
end
value = median(sqrt(total / numel(epochs)));
end

% -------------------------------------------------------------------------
function m = backgroundSer(B, Bhat, stageEpoch, stages, epochSamples, validMask)
% Somers-style SER of GEDAI on the background alone: sum B^2 / sum (Bhat - B)^2 per stage.
% On a real background this mixes legitimate artifact removal with distortion; on a
% synthetic one it is pure distortion.
rows = cell(numel(stages), 4);
for iStage = 1:numel(stages)
    [b2, e2] = deal(0);
    for iEpoch = find(stageEpoch == stages(iStage))
        cols = (iEpoch - 1) * epochSamples + 1:iEpoch * epochSamples;
        cols = cols(validMask(cols));
        b = double(B(:, cols));
        b2 = b2 + sum(b.^2, 'all');
        e2 = e2 + sum((double(Bhat(:, cols)) - b).^2, 'all');
    end
    rows(iStage, :) = {'background', bench.stageLabel(stages(iStage)), 'SER_background_dB', 10 * log10(b2 / e2)};
end
m = cell2table(rows, 'VariableNames', {'class', 'stage', 'metric', 'value'});
end

% -------------------------------------------------------------------------
function m = nullMetrics(Xhat, Bhat, stageEpoch, stages, epochSamples, validMask)
% Difference between two GEDAI runs on identical input, per stage
rows = cell(3 * numel(stages), 4);
for iStage = 1:numel(stages)
    [d2, b2, maxAbs] = deal(0);
    for iEpoch = find(stageEpoch == stages(iStage))
        cols = (iEpoch - 1) * epochSamples + 1:iEpoch * epochSamples;
        cols = cols(validMask(cols));
        d = double(Xhat(:, cols)) - double(Bhat(:, cols));
        d2 = d2 + sum(d.^2, 'all');
        b2 = b2 + sum(double(Bhat(:, cols)).^2, 'all');
        maxAbs = max(maxAbs, max(abs(d), [], 'all'));
    end
    label = bench.stageLabel(stages(iStage));
    rows(3 * iStage - 2:3 * iStage, :) = { ...
        'null', label, 'null_RRMSE', sqrt(d2 / b2); ...
        'null', label, 'null_SNR_dB', 10 * log10(b2 / d2); ...
        'null', label, 'null_maxabs_uV', maxAbs};
end
m = cell2table(rows, 'VariableNames', {'class', 'stage', 'metric', 'value'});
end

% -------------------------------------------------------------------------
function t = labelRows(m, iRun, runName, condition, scale)
n = height(m);
t = [table(repmat(iRun, n, 1), repmat({runName}, n, 1), repmat({condition}, n, 1), repmat(scale, n, 1), ...
    'VariableNames', {'run', 'runname', 'condition', 'scale'}), m];
end

% -------------------------------------------------------------------------
function groups = stageGroups(runmode, r)
% Stage groups and per-group cleaning modes, identical to bidsfun_gedai
switch runmode
    case 'StageSpecific'
        stageLogic = {-2, -3, 0, 1};
    case 'StateWise'
        stageLogic = {[-2, -3], [0, 1]};
    case 'WholeNight'
        stageLogic = {[-3, -2, 0, 1]};
    otherwise
        error('bidsfun_gedai_benchmark:runmode', 'Unknown runmode %s.', runmode);
end
groups.stageLogic = stageLogic;
groups.mode   = cellfun(@(s) resolveStageMode(s, r.GEDAIMode_dict),   stageLogic, 'uni', 0);
groups.modeBB = cellfun(@(s) resolveStageMode(s, r.GEDAIModeBB_dict), stageLogic, 'uni', 0);
end

% -------------------------------------------------------------------------
function mode = resolveStageMode(stages, dict)
% Copy of bidsfun_gedai's resolveStageMode (a local function there): one cleaning mode per
% stage group, and a group whose stages disagree is an error.
if ~isConfigured(dict)
    error('bidsfun_gedai_benchmark:unconfiguredModeDict', 'Mode dictionary is unconfigured.');
end
missing = stages(~isKey(dict, stages));
if ~isempty(missing)
    error('bidsfun_gedai_benchmark:missingStageMode', 'No mode configured for stage(s) [%s].', ...
        num2str(missing(:)', '%d '));
end
modes = unique(string(dict(stages)));
if numel(modes) > 1
    error('bidsfun_gedai_benchmark:inconsistentMode', 'Stages [%s] are cleaned together but map to %s.', ...
        num2str(stages(:)', '%d '), strjoin(modes, ', '));
end
mode = char(modes);
end

% -------------------------------------------------------------------------
function s = runForJson(r, name)
s = rmfield(r, {'GEDAIMode_dict', 'GEDAIModeBB_dict'});
s.name = name;
s.GEDAIMode = struct('stages', keys(r.GEDAIMode_dict)', 'modes', values(r.GEDAIMode_dict)');
s.GEDAIModeBB = struct('stages', keys(r.GEDAIModeBB_dict)', 'modes', values(r.GEDAIModeBB_dict)');
end

% -------------------------------------------------------------------------
function defs = metricDefinitions()
defs = struct( ...
    'SER_dB', '10*log10(sum S^2 / sum (Shat - S)^2) over event windows, Shat = GEDAI(B+S) - GEDAI(B)', ...
    'SER_raw_dB', 'as SER_dB with Shat = GEDAI(B+S) - B (unpaired; synthetic background only)', ...
    'gain', '<Shat,S>/<S,S>: fraction of injected field preserved', ...
    'ampratio', 'band-limited amplitude Shat/S at the peak channel', ...
    'morphcorr', 'correlation of Shat and S at the peak channel', ...
    'recall_in_out', 'fraction of injected events detected on their peak channel in B+S / GEDAI(B+S), thresholds frozen on B+S', ...
    'density', 'detections per minute; bg = background-only signals; excess = minus background', ...
    'SER_background_dB', '10*log10(sum B^2 / sum (GEDAI(B) - B)^2) per stage', ...
    'null', 'GEDAI(B) run twice: null_RRMSE = ||run2 - run1||/||run1||, null_SNR_dB, null_maxabs_uV', ...
    'ARR_dB', '10*log10(sum A^2 / sum (GEDAI(B+A) - GEDAI(B))^2) over artifact windows', ...
    'ARR_raw_dB', 'as ARR_dB against B instead of GEDAI(B)', ...
    'residual_gain', '<GEDAI(B+A) - GEDAI(B), A>/<A,A>: fraction of artifact left', ...
    'RRMSE_t', 'in: ||A||/||B||; out: ||GEDAI(B+A) - GEDAI(B)||/||GEDAI(B)||', ...
    'RRMSE_s', 'same on Welch PSDs, 0.5 Hz to 0.4*srate, median over channels', ...
    'CC', 'median over channels of corr(B+A, B) / corr(GEDAI(B+A), GEDAI(B))', ...
    'psd_contamination_dB', '10*log10(P(B+A)/P(B)) in the artifact bands, pooled over channels', ...
    'psd_residual_dB', '10*log10(P(GEDAI(B+A))/P(GEDAI(B))) in the artifact bands', ...
    'psd_residual_excess', '(P(GEDAI(B+A)) - P(GEDAI(B))) / (P(B+A) - P(B)) in-band');
end

% -------------------------------------------------------------------------
function writeEventsJson(file)
columns = struct( ...
    'condition', 'injection condition (signals, eog, emg, ecg)', ...
    'id', 'event id within the condition', ...
    'trial_type', 'event class (e.g. spindle_fast, eog_blink, emg_temporalL)', ...
    'kind', 'spindle, slowwave, eog, emg or ecg', ...
    'onset', 's from the start of the concatenated benchmark recording', ...
    'duration', 's', ...
    'sample_start', 'first sample in the benchmark recording', ...
    'sample_end', 'last sample in the benchmark recording', ...
    'epoch', 'benchmark epoch index', ...
    'epoch_orig', 'epoch index in the original recording (30-s epochs from its start)', ...
    'stage', 'stage digit (N3 -3, N2 -2, REM 0, Wake 1)', ...
    'anchor', 'channel whose underlying cortical patch generated the event', ...
    'peakchan', 'channel with the largest amplitude of the average-referenced field', ...
    'peakchan_idx', 'index of peakchan among the data channels', ...
    'amplitude_uV', 'target amplitude at peakchan: envelope peak (spindle), peak-to-peak (slow wave), max |x| (EOG, ECG R peak), RMS (EMG)', ...
    'freq_Hz', 'spindle centre frequency, or heart rate in Hz for ECG', ...
    'speed_mps', 'travelling-wave speed (0 = synchronous)', ...
    'coupled_to', 'id of the event this one is nested in (0 = independent)', ...
    'template', 'index into the template bank (0 = parametric waveform)');
fid = fopen(file, 'w');
fprintf(fid, '%s', jsonencode(columns, 'PrettyPrint', true));
fclose(fid);
fprintf('[JSON] %s\n', file);
end
